func (this *Cex) ParseOrder(order any, optionalArgs ...any) any {
	//
	//                "orderId": "1313003",
	//                "clientOrderId": "037F0AFEB93A",
	//                "clientId": "up421412345",
	//                "accountId": null,
	//                "status": "FILLED",
	//                "statusIsFinal": true,
	//                "currency1": "AI",
	//                "currency2": "USDT",
	//                "side": "BUY",
	//                "orderType": "Market",
	//                "timeInForce": "IOC",
	//                "comment": null,
	//                "rejectCode": null,
	//                "rejectReason": null,
	//                "initialOnHoldAmountCcy1": null,
	//                "initialOnHoldAmountCcy2": "10.23456700",
	//                "executedAmountCcy1": "25.606429",
	//                "executedAmountCcy2": "10.20904439",
	//                "requestedAmountCcy1": null,
	//                "requestedAmountCcy2": "10.20904439",
	//                "originalAmountCcy2": "10.23456700",
	//                "feeAmount": "0.02552261",
	//                "feeCurrency": "USDT",
	//                "price": null,
	//                "averagePrice": "0.3986",
	//                "clientCreateTimestamp": "1728474625320",
	//                "serverCreateTimestamp": "1728474624956",
	//                "lastUpdateTimestamp": "1728474628015",
	//                "expireTime": null,
	//                "effectiveTime": null
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var currency1 any = this.SafeString(order, "currency1")
	var currency2 any = this.SafeString(order, "currency2")
	var marketId any = nil
	if IsTrue(IsTrue(!IsEqual(currency1, nil)) && IsTrue(!IsEqual(currency2, nil))) {
		marketId = Add(Add(currency1, "-"), currency2)
	}
	market = this.SafeMarket(marketId, market)
	var symbol any = GetValue(market, "symbol")
	var status any = this.ParseOrderStatus(this.SafeString(order, "status"))
	var fee map[string]any = map[string]any{}
	var feeAmount any = this.SafeNumber(order, "feeAmount")
	if IsTrue(!IsEqual(feeAmount, nil)) {
		var currencyId any = this.SafeString(order, "feeCurrency")
		var feeCode any = this.SafeCurrencyCode(currencyId)
		AddElementToObject(fee, "currency", feeCode)
		AddElementToObject(fee, "cost", feeAmount)
	}
	var timestamp any = this.SafeInteger(order, "serverCreateTimestamp")
	var requestedBase any = this.SafeNumber(order, "requestedAmountCcy1")
	var executedBase any = this.SafeNumber(order, "executedAmountCcy1")
	// const requestedQuote = this.safeNumber (order, 'requestedAmountCcy2');
	var executedQuote any = this.SafeNumber(order, "executedAmountCcy2")
	return this.SafeOrder(map[string]any{
		"id":                  this.SafeString(order, "orderId"),
		"clientOrderId":       this.SafeString(order, "clientOrderId"),
		"timestamp":           timestamp,
		"datetime":            this.Iso8601(timestamp),
		"lastUpdateTimestamp": this.SafeInteger(order, "lastUpdateTimestamp"),
		"lastTradeTimestamp":  nil,
		"symbol":              symbol,
		"type":                this.SafeStringLower(order, "orderType"),
		"timeInForce":         this.SafeString(order, "timeInForce"),
		"postOnly":            nil,
		"side":                this.SafeStringLower(order, "side"),
		"price":               this.SafeNumber(order, "price"),
		"triggerPrice":        this.SafeNumber(order, "stopPrice"),
		"amount":              requestedBase,
		"cost":                executedQuote,
		"average":             this.SafeNumber(order, "averagePrice"),
		"filled":              executedBase,
		"remaining":           nil,
		"status":              status,
		"fee":                 fee,
		"trades":              nil,
		"info":                order,
	}, market)
}

