func (this *Cex) ParseTransfer(transfer any, optionalArgs ...any) any {
	//
	// transferBetweenSubAccounts
	//
	//    {
	//        "ok": "ok",
	//        "data": {
	//            "transactionId": "30225415"
	//        }
	//    }
	//
	// transfer between main/sub
	//
	//     {
	//         "ok": "ok",
	//         "data": {
	//             "accountId": "sub1",
	//             "clientTxId": "27ba8284-67cf-4386-9ec7-80b3871abd45",
	//             "currency": "USDT",
	//             "status": "approved"
	//         }
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var currencyId any = this.SafeString(transfer, "currency")
	var currencyCode any = this.SafeCurrencyCode(currencyId, currency)
	return map[string]any{
		"info":        transfer,
		"id":          this.SafeString2(transfer, "transactionId", "clientTxId"),
		"timestamp":   nil,
		"datetime":    nil,
		"currency":    currencyCode,
		"amount":      nil,
		"fromAccount": nil,
		"toAccount":   nil,
		"status":      this.ParseTransactionStatus(this.SafeString(transfer, "status")),
	}
}

